        position: "absolute",
        left: rect.left,
        top: rect.top,
        width: rect.width,
        height: rect.height,
        overflow: "hidden",
        pointerEvents: "none",
      }}
    >
      <div
        style={{
          position: "absolute",
          inset: "-30%",
          background: "conic-gradient(from 0deg, var(--dark-pink), var(--armed-glow), var(--dark-pink))",
